insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '7240e831-34b5-5185-b013-de08d2d9bb0e', id, null, 15, '4', 'Escrever um parágrafo sobre alguma das coisas positivas em sua família. Incluir as coisas das quais você se orgulha e as boas qualidades e realizações de sua família.', '2026-11-02 18:45:15', null from especialidades where codigo = 'AM-012' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
