insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'e3afc3ff-eede-51b1-aec6-40e8cfa7dd70', id, null, 17, '6', 'Fazer uma lista de atividades familiares que você acha que sua família gostaria. Fazer pelo menos uma dessas atividades em cumprimento da especialidade.', '2026-11-02 18:45:15', null from especialidades where codigo = 'AM-012' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '9b24a654-23f1-57ad-b907-e80acb063ce7', id, null, 18, '7', 'Durante 1 mês, com o máximo possível de membros de sua família, criar uma rotina para o Culto Familiar, Matutino (pela manhã) ou Vespertino (à tarde ou noite), assim como os Cultos de Pôr-do-sol de Sexta Feira.', '2026-11-02 18:45:15', null from especialidades where codigo = 'AM-012' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'ffe92099-a026-5dc4-a779-7271742ea9f3', id, null, 19, '8', 'Mencionar 5 maneiras de demonstrar atenção, interação e interesse por seus vizinhos. Colocar uma dessas maneiras em prática. Fazer um relatório do resultado.', '2026-11-02 18:45:15', null from especialidades where codigo = 'AM-012' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
