insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '95ace527-2e44-5609-8a6f-f694b3f9bc08', id, null, 1, '1', 'Memorizar e assinar o Voto de Temperança: "Consciente de que o uso do álcool e fumo e o uso de drogas não recomendadas por médicos não é compatível com um viver saudável, comprometo-me a não apenas me abster do uso dessas substâncias e viver de acordo com os princípios da Temperança Cristã, mas também a ajudar os outros a compreender e aceitar esse estilo mais saudável de vida"; ou criar seu próprio voto.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
