insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'a6bbdd63-14f7-5c1a-b7ba-98f91a028778', id, 'a530152a-9018-5fb0-a0e4-b1acdd4bbcb2', 10, '2.a.7', 'Um verso de sua escolha que ressalte a importância da temperança em nossa vida espiritual.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '7ec47cee-b449-5011-b2ed-62f1b6470d40', id, 'd3a9d169-aefb-5282-aad5-653dfc0f3bf3', 11, '2.b', 'Espírito de Profecia', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '9a47d61f-b3a2-5fa4-8a0b-19825160e0bb', id, '7ec47cee-b449-5011-b2ed-62f1b6470d40', 12, '2.b.1', '"A verdadeira temperança nos ensina a abstermo-nos inteiramente daquilo que é prejudicial, e usar com parcimônia apenas alimentos saudáveis e nutritivos" Temperança, pág. 138.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '1e211768-99f4-5ddd-860c-16c24a1575ae', id, '7ec47cee-b449-5011-b2ed-62f1b6470d40', 13, '2.b.2', 'O único caminho seguro é não tocar, não provar, não manusear chá, café, vinhos, o fumo, ópio e bebidas alcoólicas" Conselhos Sobre Regime Alimentar, pág. 428.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '60a54d3a-62a1-5fd9-9d26-34551a7f5241', id, '7ec47cee-b449-5011-b2ed-62f1b6470d40', 14, '2.b.3', '"... a temperança por si só é o fundamento de todas as graças que vêm de Deus, o fundamento de todas as vitórias a serem alcançadas." Temperança, pág. 201.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'cd92dcb2-4029-56a1-8d9e-49ee6f269934', id, '7ec47cee-b449-5011-b2ed-62f1b6470d40', 15, '2.b.4', '"Uma vida pura e nobre, uma vida de vitória sobre o apetite e o desejo, é possível a todos que unirem a fraca vontade humana à onipotente e Inabalável vontade de Deus." Temperança, pág. 113.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '8f847d28-2394-51bb-a2f0-0535192baf90', id, '7ec47cee-b449-5011-b2ed-62f1b6470d40', 16, '2.b.5', 'O tabaco é um lento, porém maligno veneno. Em quaisquer das formas que é usado, depõe contra a constituição; e torna-se mais perigoso porque seus efeitos são lentos, e, à primeira vista, imperceptíveis." - Medicina e Salvação, pág. 327, 328.', '2026-10-20 11:49:52', null from especialidades where codigo = 'AM-013' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
