insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'd95f4d4a-6275-5724-a7f0-b3fe167fdee7', id, '126550f2-48b9-580e-857d-3acac7a76c8c', 13, '7.a', 'Fazer uma pesquisa em seu bairro ou comunidade levantando interessados em receber orações de seu grupo. Manter uma relação de endereços desses e, ao final do período de pelo menos 2 semanas, oferecer um estudo bíblico e convidá-los para uma programação especial de sua Igreja.', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '51a43f65-1dc9-5063-a0f3-d030d5a503d8', id, '126550f2-48b9-580e-857d-3acac7a76c8c', 14, '7.b', 'Manter uma relação de e-mails e telefones de membros de seu Clube e Igreja. Durante os cultos de oração de sua Igreja, listar cada novo pedido e enviar mensagens aos membros da relação para que orem, a fim de formar uma rede de oração.', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '684467c4-9644-5e45-9bfe-ac30b786a298', id, '126550f2-48b9-580e-857d-3acac7a76c8c', 15, '7.c', 'Criar um canal (site, blog, perfil em rede social, lista de WhatsApp, etc) que possa receber pedidos de oração. Divulgá-lo em sua comunidade e para seus amigos. Fazer com que todos os pedidos recebidos sejam encaminhados a pessoas que possam orar pelos mesmos, incluindo você.', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '75a62132-12c0-5c6c-94b3-cd5d77b0476c', id, null, 16, '8', 'Durante, ao menos, 2 reuniões de seu Clube, participar de um momento de oração intercessora, onde os membros possam expressar seus pedidos de oração, orar uns pelos outros e anotar os pedidos dos demais para orar durante a semana.', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'aac24c56-a787-52f2-bf19-22897fddecb8', id, null, 17, '9', 'Em consulta com seu Diretor, fazer uma lista de desbravadores ausentes de seu Clube e orar por eles pelo período mínimo de 30 dias. Em conjunto com seu grupo que está cumprindo a especialidade, visitá-los ou, na impossibilidade, enviar uma mensagem informando o fato de terem orado por eles por esse período. Perguntar se sentem o desejo de regressar e convidá-los a retornar ao Clube.', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'e2613140-c9c2-5e33-a408-15c817be7c2f', id, null, 18, '10', 'Estabelecer um horário bem definido para suas orações. Explicar por que escolheu esse horário. Em uma entrevista com o seu Pastor ou Ancião, descubrir como é possível seguir a recomendação de 1 Tessalonicenses 5:17.', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '002aa468-52ce-58c0-a2b4-5c61b80b8d80', id, null, 19, '11', 'Fazer um relatório sobre suas experiências ao realizar os requisitos dessa especialidade. Citar os pontos positivos encontrados e observados. O que melhorou em sua vida durante esse período? Você gostaria de continuar intercedendo por outros? Por quê?', '2026-11-02 13:31:52', null from especialidades where codigo = 'AM-042' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
